-- (가)
SELECT COUNT(*) FROM BOOK WHERE PUB_YEAR BETWEEN 2020 AND 2015;

-- (나)
SELECT COUNT(*) FROM BOOK WHERE PUB_YEAR NOT BETWEEN 2015 AND 2020;

-- (가)
SELECT COUNT(*) FROM SHELF WHERE CALL_NO LIKE '005._%';

-- (나)
SELECT COUNT(*) FROM SHELF WHERE CALL_NO LIKE '0__%';

SELECT LOAN_ID
  FROM LOAN
 ORDER BY MEM_ID, RET_DAY DESC;

SELECT M.NAME, G.GRADE
  FROM MEMBER M, GRADE_RULE G
 WHERE M.POINT BETWEEN G.LO AND G.HI;

-- (가)
SELECT COUNT(*) FROM MEMBER
 WHERE REGEXP_LIKE(MEM_ID, '^LIB[0-9]{2,3}$');

-- (나)
SELECT COUNT(*) FROM MEMBER
 WHERE REGEXP_LIKE(MEM_ID, '^LIB[0-9]{2,3}$', 'i');

SELECT REGEXP_SUBSTR('SQL,,DB,AI', '[^,]+', 1, 3) AS A,
       REGEXP_COUNT('SQL,,DB,AI', '[^,]+')        AS B
  FROM DUAL;

UPDATE MEMBER
   SET LOAN_CNT = LOAN_CNT + 1,
       PREV_CNT = LOAN_CNT;

UPDATE reserve SET st = '완료' WHERE rsv_id = 1;
SAVEPOINT sp1;
DELETE FROM reserve WHERE rsv_id = 2;
ROLLBACK TO sp1;
INSERT INTO reserve VALUES (3, '대기');
COMMIT;
UPDATE reserve SET st = '취소';
ROLLBACK;
SELECT COUNT(*) FROM reserve WHERE st = '대기';

